package local.pocketchat;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.zip.*;
public class SavedFileTestActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);try{if(getIntent().getBooleanExtra("previewPdf",false)){startActivity(new Intent(this,AttachmentPreviewActivity.class).putExtra("uri","content://local.pocketchat.download-fixture/sample2.pdf").putExtra("name","sample.pdf").putExtra("mime","application/pdf"));finish();return;}Uri uri=Uri.parse(getIntent().getStringExtra("uri"));byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){bytes=J.read(in,16*1024*1024);}boolean body=false,rels=false;try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;while((e=zip.getNextEntry())!=null){body|=e.getName().equals("word/document.xml");rels|=e.getName().equals("_rels/.rels");}}J.write(new File(getFilesDir(),"system-save-results.json"),J.obj("systemDocumentPickerUsed",true,"savedFileReadable",true,"bytes",bytes.length,"validDocxDocument",body,"relationshipsPresent",rels).toString(2));}catch(Exception e){try{J.write(new File(getFilesDir(),"system-save-results.json"),J.obj("savedFileReadable",false,"errorType",e.getClass().getSimpleName()).toString(2));}catch(Exception ignored){}}finish();}
}
